def priority(task, state, m=4.0, k=0.8, late_boost=10.0, spt_w=1.0, urg_w=1.0, urg_scale=2.0):
    # Premium: lateness escalation. Standard: blend SPT (p90 tail) with a
    # deadline-urgency term that only matters when slack is small.
    import math
    now = state.now
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = max(0.0, task.due - est - now)
    if task.tenant == 'premium':
        base = m * task.weight / est * math.exp(-slack / (k * mean_est))
        lateness = now + est - task.due
        return base * (1.0 + late_boost * max(0.0, lateness) / est)
    else:
        spt = spt_w * task.weight / est
        urg = urg_w * math.exp(-slack / (urg_scale * mean_est))
        return spt + urg  # tuned (m=8.73,k=1.47,late_boost=5.61,spt_w=0.527,urg_w=0.686,urg_scale=3.85)

