    ratio = wait / est
    if ratio >= c:
        return 1e6 + urgency
    if task.tenant == 'premium':
        return urgency * (1.0 + g * ratio)
    return urgency  # tuned (m=18.5,k=7.31,g=8.67,c=0.338)

