    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    # direct due-awareness: penalize tasks whose projected finish exceeds due
    projected_late = (state.now + est) - task.due
    if projected_late > 0:
        atc *= 1.0 + due_w * projected_late / est
    load = state.queue_work / max(state.capacity, 1e-6)
    if task.tenant == 'premium':
        # premium already handled by due term + tier; small extra if truly urgent
        if slack <= 0.0:
            atc *= 1e3
    else:
        # standard: SPT bias under load to cut p90, otherwise modest short-job tilt
        if load > load_thresh:
            atc *= 1.0 + spt_w / est * 2.0
        else:
            atc *= 1.0 + spt_w / est
    return atc  # tuned (k=15.6,m=1.87,due_w=3.05,spt_w=1.49,load_thresh=0.278)

