        return m / est + m * math.exp(-max(slack, 0.0) / (decay * mean_est))
    # standard: SRPT with relative aging, boost long-waiting tasks for p90 tail
    base = 1.0 / est
    rel_wait = wait / (est + mean_est)
    base *= (1.0 + age * rel_wait * (1.0 + pressure))
    # extra boost for very old tasks to cut p90 tail
    if wait > p90_boost * mean_est:
        base *= (1.0 + rel_wait)
    return base  # tuned (m=2.52,age=1.91,decay=0.597,p90_boost=1.71)

